using UnityEngine;

public class PlayerController : MonoBehaviour
{
    // Referencias cacheadas — buscar UNA vez en Awake
    private Rigidbody rb;
    private Animator animator;
    private AudioSource audioSource;

    void Awake()
    {
        // GetComponent<T>() busca el componente en este GameObject
        rb = GetComponent<Rigidbody>();
        animator = GetComponent<Animator>();
        audioSource = GetComponent<AudioSource>();

        // Verificar null después de GetComponent
        if (rb == null)
        {
            Debug.LogError("No se encontró Rigidbody en " + gameObject.name);
        }
    }

    void Update()
    {
        // Usamos las referencias cacheadas — NO GetComponent aquí
        float h = Input.GetAxis("Horizontal");
        animator.SetFloat("Speed", Mathf.Abs(h));
    }
}

using UnityEngine;

public class CollisionHandler : MonoBehaviour
{
    void OnCollisionEnter(Collision collision)
    {
        // TryGetComponent: no lanza excepción si no existe
        // Usa 'out' para recibir el componente si se encuentra
        if (collision.gameObject.TryGetComponent<Enemy>(out Enemy enemy))
        {
            enemy.TakeDamage(10);
        }

        // Alternativa con GetComponent (menos segura):
        // Enemy enemy = collision.gameObject.GetComponent<Enemy>();
        // if (enemy != null) enemy.TakeDamage(10);

        // GetComponentInChildren: busca en hijos también
        Collider col = GetComponentInChildren<Collider>();

        // GetComponentInParent: busca en padres
        Canvas canvas = GetComponentInParent<Canvas>();
    }
}

using UnityEngine;

// RequireComponent garantiza que Rigidbody siempre exista
// Unity lo agrega automáticamente y no permite eliminarlo
[RequireComponent(typeof(Rigidbody))]
[RequireComponent(typeof(Collider))]
public class PhysicsObject : MonoBehaviour
{
    private Rigidbody rb;

    void Awake()
    {
        // Seguro: RequireComponent garantiza que existe
        rb = GetComponent<Rigidbody>();
    }
}

// [SerializeField] expone campos privados al Inspector
public class EnemyStats : MonoBehaviour
{
    [SerializeField] private float health = 100f;
    [SerializeField] private float speed = 5f;
    [SerializeField] private Transform target; // Arrastra desde el Inspector
}

